// ui/routes/chat/ask.mjs — feature "chat" (docs/chat.md). Generated by tools/split-by-feature.mjs v1;
// the body of register() was moved verbatim from ui/server.mjs. Edit it here from now on.
import { findPipelineRowById, folderFacts, listArtifacts, listRunArtifacts, readPipelineStateById, readPrState, readRunResultsForRow, sourceShipFacts } from '../../../src/core/artifacts.mjs';
import { askMcpPreview, validateMcpOff } from '../../../src/core/ask/mcp.mjs';
import { askCatalog } from '../../../src/core/ask/models.mjs';
import { validateClientContext } from '../../../src/core/ask/prompt.mjs';
import { RUN_CARD_ARTIFACTS, RUN_CARD_FINISHED, lastArtifactsWindow, runCardResults } from '../../../src/core/ask/run-card-extras.mjs';
import { countAttachments as askCountAttachments, countThreads as askCountThreads, countWorktrees as askCountWorktrees, getThread as askGetThread } from '../../../src/core/ask/store.mjs';
import { WORK_ARTIFACT_KIND } from '../../../src/core/no-project-work.mjs';
import { getWatch, stoppedWatchFact } from '../../../src/core/pr-watch.mjs';
import { PROXY_AGENT_TEXT } from '../../../src/core/proxy-host.mjs';
import { isInContainer } from '../../../src/core/remote-access.mjs';
import { answererProfileFor, chatHomePinsFor, setAnswererProfileFor, setChatHomePinsFor } from '../../../src/core/settings.mjs';
import { featureOfPipeline } from '../../../src/core/shape/features.mjs';
import { roundsOf } from '../../../src/core/shape/rounds.mjs';
import { isNoProjectKey } from '../../../src/core/store.mjs';
import { REFS_MAX } from '../../../src/shared/chip-refs.mjs';
import { REMOTE_MODE, agentMayBeCaller, askCommandBridges, askCommands, askCommandsEnabled, askIdParam, askLiveRun, askProxyBridges, askRefResolver, askRelays, askRunFromPipelineRow, askRunningCount, askThreadVisible, askTurnEngine, askViewer, badRequest, builtins, liveRunEntry, proxyHost, relayAskLine, terminalSameOrigin } from '../../server.mjs';

export function register(app) {

app.post('/api/ask/commands', async (req, res) => {
  if (!isInContainer(req)) return res.status(403).json({ error: 'commands: loopback callers only' });   // the /api/ask/relay gate
  const threadId = askCommandBridges.get(String(req.headers['x-worca-ask-command'] || ''));
  if (!threadId) return res.status(403).json({ error: 'commands: unknown or finished turn' });
  if (!askCommandsEnabled()) return res.status(403).json({ error: 'The terminal is turned off on this Worca.' });
  const op = req.body && req.body.op;
  const input = (req.body && typeof req.body.input === 'object' && req.body.input) || {};
  const fn = { run: askCommands.run, read: askCommands.read, wait: askCommands.wait, stop: askCommands.stop, list: askCommands.list }[op];
  if (!fn) return badRequest(res, 'commands: unknown op');
  try { res.json({ result: await fn(threadId, input) }); }
  catch (e) { res.status(e?.code === 'NOT_FOUND' ? 404 : 409).json({ error: e?.message || String(e), code: e?.code || null }); }
});

/** The panel's Agent switch: shown only where agent mode can work. Same-origin, like GET /api/terminal. */
app.get('/api/ask/commands/status', (req, res) => {
  res.json({ enabled: terminalSameOrigin(req) && !agentMayBeCaller(req) && askCommandsEnabled() });
});

app.post('/api/ask/relay', async (req, res) => {
  if (!isInContainer(req)) return res.status(403).json({ error: 'relay: loopback callers only' });
  const token = String(req.headers['x-worca-relay'] || '');
  if (!askRelays.has(token)) return res.status(403).json({ error: 'relay: unknown or finished turn' });
  const line = req.body && typeof req.body.line === 'string' ? req.body.line : null;
  if (line === null) return badRequest(res, 'relay: line is required');
  // The same answerer a worker's `relay` frame reaches (src/core/executor/controller.mjs relayAskLine).
  const r = await relayAskLine(token, line);
  if (r.error) return res.status(403).json({ error: r.error });
  res.json({ out: r.lines });
});

// The Chat home's pinned workflows (src/shared/home-pins.mjs): one ordered list per person, in settings.json.
app.get('/api/chat-home/pins', (req, res) => {
  res.json({ pins: chatHomePinsFor(askViewer(req)) });
});
app.put('/api/chat-home/pins', async (req, res) => {
  try {
    res.json({ pins: await setChatHomePinsFor(askViewer(req), (req.body || {}).pins) });
  } catch (err) {
    if (err && err.code === 'BAD_HOME_PINS') return badRequest(res, err.message);
    res.status(500).json({ error: String((err && err.message) || err) });
  }
});
// The answerer profile (src/shared/answerer.mjs): the lead perspective this person shapes as, keyed like the pins.
app.get('/api/answerer', (req, res) => {
  res.json(answererProfileFor(askViewer(req)));
});
app.put('/api/answerer', async (req, res) => {
  try {
    res.json(await setAnswererProfileFor(askViewer(req), { lead: (req.body || {}).lead }));
  } catch (err) {
    if (err && err.code === 'BAD_LEAD') return res.status(400).json({ error: { code: 'BAD_LEAD', message: err.message } });
    res.status(500).json({ error: String((err && err.message) || err) });
  }
});
app.post('/api/ask/proxy', async (req, res) => {
  if (!isInContainer(req)) return res.status(403).json({ error: 'proxy: loopback callers only' });
  if (!askProxyBridges.has(String(req.headers['x-worca-ask-proxy'] || ''))) return res.status(403).json({ error: 'proxy: unknown or finished turn' });
  if (agentMayBeCaller(req)) return res.status(403).json({ error: PROXY_AGENT_TEXT, code: 'PROXY_AGENT_BLOCKED' });
  const op = req.body && req.body.op;
  if (op === 'status') return res.json({ result: proxyHost.chatStatus() });
  if (op === 'test') {
    // proxyHost.test() releases its lock in `finally`; a throw from checkUpstream still needs a JSON reply here
    // (the MCP child reads j.error).
    try {
      const r = await proxyHost.test();
      return res.json({ result: r.status === 200 ? r.body : { ok: false, ...r.body } });
    } catch (err) {
      return res.status(500).json({ error: `the proxy test failed: ${err && err.message ? err.message : String(err)}` });
    }
  }
  return badRequest(res, 'proxy: unknown op');
});

// Settings → "Delete all chat history": the counts the confirm dialog quotes,
// read fresh right before it opens.
app.get('/api/ask/history', (req, res) => {
  try {
    res.json({
      threads: askCountThreads({ visibleTo: askViewer(req), mode: 'any' }),
      worktrees: askCountWorktrees(),
      attachments: askCountAttachments(),
      inFlight: askRunningCount(),
    });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

/** Chat P3 (CONTRACT §5): what the chat run card's result region shows for a FINISHED run (done/stopped/error) —
 *  results.json's counts and top files by churn, the LAST artifacts (the newest outputs), the PR. Null for a run
 *  that is not over (results.json is written at the end) or a row that is gone. Every read is best-effort: a missing
 *  piece is null / [] (a stop or error with no changes writes no results.json). */
async function askRunCardExtras(row) {
  if (!row || !RUN_CARD_FINISHED.has(String(row.status || ''))) return null;
  let results = null;
  try {
    results = runCardResults(await readRunResultsForRow(row));
  } catch { results = null; }            // no results.json, a reclaimed run folder, or junk JSON
  let artifacts = [];
  let moreArtifacts = false;
  let artifactsTotal = null;
  try {
    // Count on the cheap index rows (no stat), then read (and stat) only the last page.
    const { total, offset } = lastArtifactsWindow(await listArtifacts(row.id), RUN_CARD_ARTIFACTS);
    const pick = (rows) => rows.map((a) => ({ kind: a.kind, relPath: a.relPath, bytes: a.bytes, nodeId: a.nodeId, cycle: a.cycle }));
    if (isNoProjectKey(row.project_key)) {
      // P3: a run without a project — its work/ files (the deliverables) first, then its newest other rows; the caption
      // counts every browsable row (Artifacts · <n>).
      const work = total ? await listRunArtifacts(row.id, { kind: WORK_ARTIFACT_KIND, limit: RUN_CARD_ARTIFACTS }) : [];
      const others = work.length < RUN_CARD_ARTIFACTS && total > work.length
        ? (await listRunArtifacts(row.id, { limit: RUN_CARD_ARTIFACTS, offset, browsableOnly: true })).filter((a) => a.kind !== WORK_ARTIFACT_KIND)
        : [];
      artifacts = pick([...work, ...others].slice(0, RUN_CARD_ARTIFACTS));
      artifactsTotal = total;
      moreArtifacts = total > artifacts.length;
    } else {
      const rows = total ? await listRunArtifacts(row.id, { limit: RUN_CARD_ARTIFACTS, offset, browsableOnly: true }) : [];
      artifacts = pick(rows);
      moreArtifacts = total > RUN_CARD_ARTIFACTS;
    }
  } catch { /* the artifact index is best-effort here */ }
  const pr = readPrState(row.id);
  let rounds = [];
  try { rounds = roundsOf([row.id]).get(row.id) || []; } catch { rounds = []; }
  let watch = null;
  try { watch = pr && pr.url ? stoppedWatchFact(getWatch(pr.url)) : null; } catch { watch = null; }
  let source = null;                                   // a run on its source branch: the run page's Push facts
  try { source = await sourceShipFacts(row, (readPipelineStateById(row.id) || {}).projectDir || null); } catch { source = null; }
  const { changes } = folderFacts(row);                // S9: a folder row's { state, counts }; git rows carry none
  return { results, artifacts, moreArtifacts, ...(artifactsTotal != null ? { artifactsTotal } : {}), pr, rounds, watch, ...(source ? { source } : {}), ...(changes ? { changes } : {}) };
}

// Ask Worca progress card hydration (plan D9): the run's detail state by pipeline id OR live run id, no store key.
// Chat P3: plus `extras` (askRunCardExtras) for the chat run card's result region.
const ASK_RUN_REF_RE = /^(?:[0-9a-f]{8}|[0-9a-zA-Z-]{9,64})$/;
app.get('/api/ask/runs/:id', async (req, res) => {
  const id = String(req.params.id || '');
  if (!ASK_RUN_REF_RE.test(id)) return res.status(400).json({ error: 'invalid run id' });
  try {
    const entry = liveRunEntry(id);
    const row = findPipelineRowById(entry && entry.pipelineId ? entry.pipelineId : id);
    // A deleted run keeps an anonymised row (deleted_at) for Statistics; the chat card must still read it as gone.
    if (!row || row.deleted_at) return res.status(404).json({ error: 'run not found' });
    const state = readPipelineStateById(row.id);
    // Shape it first, plan in slices: state.shaping is in memory only (F46), so a finished or unloaded slice 1 would
    // lose its feature strip. The feature row is durable. Best effort.
    if (!state.shaping) {
      try {
        const at = featureOfPipeline(state.id);
        if (at && at.idx === 1) state.shaping = { feature: { id: at.featureId, index: 1 } };
      } catch { /* the feature tables are best-effort here */ }
    }
    const extras = await askRunCardExtras(row);
    res.json({ state, live: entry ? { runId: entry.id, status: entry.status } : null, extras });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});
/** One run for a chip, by History id or app run id: the live entry's title, status and pause cause first (fresher
 *  than the row), the saved row's #history home. A saved run's pause cause rides resume_point, read the way
 *  rowToState reads it. A live run with no History row yet answers its app run id only (id null). null when
 *  neither the runs Map nor the DB knows it. */
function askRefRun(id) {
  const entry = liveRunEntry(id);
  const pid = (entry && entry.pipelineId) || (/^[0-9a-f]{8}$/.test(id) ? id : null);
  const row = pid ? findPipelineRowById(pid) : null;
  if (!row && !entry) return null;
  const saved = row ? askRunFromPipelineRow(row) : null;
  const live = entry ? askLiveRun(entry.id) : null;
  let rp = null;
  try { rp = row && row.resume_point ? JSON.parse(row.resume_point) : null; } catch { rp = null; }
  return {
    id: saved ? saved.id : pid, runId: entry ? entry.id : null,
    title: (live && live.title) || (saved && saved.title) || '',
    status: (live && live.status) || (saved && saved.status) || '',
    pauseReason: entry ? (entry.pauseReason || null) : (rp && typeof rp.pauseReason === 'string' ? rp.pauseReason : null),
    home: row ? (row.workspace_key ? `workspaces/${row.workspace_key}` : (row.project_key || null)) : (live ? live.home : null),
  };
}
app.post('/api/ask/refs/resolve', async (req, res) => {
  const refs = req.body && req.body.refs;
  if (!Array.isArray(refs) || refs.length > REFS_MAX || !refs.every((k) => typeof k === 'string' && k.length <= 300)) {
    return badRequest(res, `refs must be an array of at most ${REFS_MAX} ref keys`);
  }
  try {
    res.json({ refs: await askRefResolver.resolve(refs, {
      run: askRefRun,
      chat: (id) => {
        const thread = askGetThread(id);
        return thread && thread.mode !== 'composer' && askThreadVisible(thread, req) ? { title: thread.title || '' } : null;
      },
      external: !agentMayBeCaller(req),
    }) });
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// Show in folder (docs/show-files.md): a chat files card opens the file manager on the file a show_files copy was made
// from. It opens on THIS machine, so never on a hosted worca, never for a caller that may be an agent, and only where a
// file manager was found. The path never leaves the server: the card holds a `source` flag, this route reads the row.
const askRevealAvailable = (req) => !REMOTE_MODE && !agentMayBeCaller(req) && !!builtins().fileManager;
app.get('/api/ask/reveal', (req, res) => {
  res.json({ available: askRevealAvailable(req), label: askRevealAvailable(req) ? builtins().fileManager.label : null });
});

// D8/§8.1: the chat model catalog. Fresh per request (the /api/config
// precedent) — a cache would go stale against global-model edits.
app.get('/api/ask/models', async (_req, res) => {
  try {
    res.json(await askCatalog());
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// MCP registry §9.4: the composer picker's data — the same targets in play and resolver as the turn. `threadId`
// adds the thread's open worktrees and stored choices; a body `mcpOff` overrides them (a thread-less chat);
// `model` (the composer's) sets the §5.6 tool-name limit.
app.post('/api/ask/mcp-preview', async (req, res) => {
  try {
    const body = req.body || {};
    const cv = validateClientContext(body.context);
    if (!cv.ok) return badRequest(res, cv.error);
    let thread = null;
    if (body.threadId !== undefined) {
      const tid = askIdParam(res, body.threadId, 'thread');
      if (!tid) return;
      thread = askGetThread(tid);
      // Someone else's thread is a 404, like every /api/ask/threads/:id route on a shared deployment.
      if (!thread || !askThreadVisible(thread, req)) return res.status(404).json({ error: 'thread not found' });
    }
    const mo = body.mcpOff === undefined ? { ok: true, value: thread ? thread.mcpOff : null } : validateMcpOff(body.mcpOff);
    if (!mo.ok) return badRequest(res, mo.error);
    if (body.model !== undefined && (typeof body.model !== 'string' || !body.model || body.model.length > 200)) return badRequest(res, 'model must be a model id');
    // The chat's engine (D12): the one it is locked to, else the picked model's — a Codex chat gets skills only (#635).
    const previewEngine = (thread ? askTurnEngine(thread.id, thread, body.model ?? null) : askTurnEngine(null, null, body.model ?? null)) || 'claude';
    res.json(await askMcpPreview({ ctx: cv.context, threadId: thread ? thread.id : null, off: mo.value, model: body.model ?? null, engine: previewEngine }));
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});
}
